(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zzn-sj-prepa-gyneco-j9-sf3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zzn-sj-prepa-gyneco-j9-sf3\",\n \"titre\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 40,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n   \"sha256\": \"c1e8c2d8402d3b954a7c6fc159ceb6b02b83cb88c53adce6ddd9268aa4b95034\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n     \"slug\": \"prepa-gyneco-j9-sf3\",\n     \"pages\": \"\",\n     \"count\": 40,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Gynéco-obstétrique\",\n     \"source\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__0\",\n       \"num\": \"1\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lequel (s) de ces gestes ne fait (font) pas partie des objectifs de la consultation au premier trimestre de la grossesse ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Dépister les pathologies pouvant compliquer la grossesse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Déclarer la grossesse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Calculer le terme de la grossesse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Étudier la morphologie fœtale\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Établir le pronostic de l'accouchement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. Étudier la morphologie fœtale ; E. Établir le pronostic de l'accouchement\",\n       \"answerLetters\": [\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Au premier trimestre, la CPN vise à confirmer et déclarer la grossesse, déterminer l'âge gestationnel et la date probable d'accouchement, et dépister les facteurs de risque ou pathologies maternelles ; l'étude morphologique détaillée du fœtus s'effectue au 2e trimestre (20-22 SA) et le pronostic de l'accouchement s'établit au 3e trimestre (CPN du 9e mois).\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Surveillance prénatale (CPN) et explorations en obstétrique (p. 192).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__1\",\n       \"num\": \"2\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les examens paracliniques suivants doivent être obligatoirement prescrits aux gestantes pendant toutes les périodes de la grossesse :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La sérologie de la syphilis\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La sérologie de la toxoplasmose\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La sérologie de la rubéole\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'électrophorèse de l'hémoglobine\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le taux d'hémoglobine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. Le taux d'hémoglobine\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"Parmi les examens du bilan prénatal, le taux d'hémoglobine (ou NFS) est contrôlé régulièrement à chaque trimestre pour dépister l'anémie gravidique ; les sérologies de la rubéole et de la syphilis sont demandées au 1er trimestre, et l'électrophorèse de l'hémoglobine une seule fois si inconnue.\\n\\nSource : Cours de Gynéco-Obstétrique — Bilan prénatal courant et priorités d'examens.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__2\",\n       \"num\": \"3\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La première dose de l'association sulfadoxine-pyriméthamine peut être administrée à la gestante :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Dès la 16ème semaine d'aménorrhée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Avant la 16ème semaine de grossesse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Uniquement si la patiente sent les mouvements actifs du fœtus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Aux alentours du 5ème mois de la grossesse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Dès la 16ème semaine d'aménorrhée\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Selon les directives nationales de prévention du paludisme chez la femme enceinte, le Traitement Préventif Intermittent (TPI) à la Sulfadoxine-Pyriméthamine (SP) est formellement contre-indiqué au 1er trimestre et débute dès le début du 2e trimestre, à partir de la 16ème semaine d'aménorrhée (ou dès l'apparition des mouvements actifs fœtaux), puis est renouvelé chaque mois jusqu'à l'accouchement.\\n\\nSource : Cours de Gynéco-Obstétrique — Paludisme et grossesse (TPI à la SP).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__3\",\n       \"num\": \"4\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lesquels des paramètres suivants constituent-ils des éléments d'un bon pronostic d'accouchement par voie basse au terme de la grossesse ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Un segment inférieur de l'utérus bien amplié\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une hauteur utérine égale à 33 centimètres\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"De bonnes contractions utérines\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le promontoire du bassin osseux maternel perçu à bout de doigt\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Un segment inférieur de l'utérus bien amplié ; B. Une hauteur utérine égale à 33 centimètres ; C. De bonnes contractions utérines\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"À terme, un segment inférieur souple et bien amplié, une hauteur utérine normale (32-34 cm, témoignant d'un fœtus eutrophique sans macrosomie ni hydramnios) et une bonne dynamique utérine sont des éléments favorables à l'accouchement par voie basse ; en revanche, un promontoire accessible au toucher vaginal signe un bassin rétréci (mauvais pronostic).\\n\\nSource : Cours de Gynéco-Obstétrique — Pronostic de l'accouchement en fin de grossesse (p. 8).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__4\",\n       \"num\": \"5\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La carence en acide folique au cours de la grossesse peut entraîner les anomalies fœtales suivantes :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'anencéphalie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les réponses a, b, c et d\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le bec de lièvre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une malformation cardiaque\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le spina bifida\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Les réponses a, b, c et d\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La carence périconceptionnelle et au 1er trimestre en acide folique (vitamine B9) est responsable d'anomalies de fermeture du tube neural (spina bifida, anencéphalie) ainsi que d'un risque accru de fentes labiopalatines (bec de lièvre) et de cardiopathies congénitales, d'où l'intérêt de regrouper toutes ces propositions.\\n\\nSource : Cours de Gynéco-Obstétrique — Supplémentation en fer et acide folique au cours de la grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__5\",\n       \"num\": \"6\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lesquels des signes suivants annoncent-ils une rupture imminente de l'utérus au cours du travail d'accouchement ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La présence de métrorragies\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une tension douloureuse des ligaments ronds\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une dilatation stationnaire du col utérin\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une déformation de l'utérus en sablier\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Une ascension de l'anneau de Bandl-Frommel\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Une tension douloureuse des ligaments ronds ; D. Une déformation de l'utérus en sablier ; E. Une ascension de l'anneau de Bandl-Frommel\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Le syndrome de pré-rupture utérine (syndrome de Bandl-Frommel) associe une hypercinésie/hypertonie douloureuse, une tension douloureuse des ligaments ronds (perçus comme deux cordes tendues), l'ascension progressive de l'anneau de rétraction de Bandl vers l'ombilic et la déformation caractéristique de l'utérus en sablier (ou en brioche). Les métrorragies apparaissent une fois la rupture constituée.\\n\\nSource : Cours de Gynéco-Obstétrique L3 / SONU — La rupture utérine : phase de pré-rupture.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__6\",\n       \"num\": \"7\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le traitement en deuxième intention de l'hémorragie de la délivrance par atonie utérine consiste :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"En l'introduction intra-rectale de 5 comprimés de misoprostol\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"En l'injection intraveineuse de syntocinon\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"En la pose du ballonnet intra-utérin\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Au massage continu de l'utérus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. En l'introduction intra-rectale de 5 comprimés de misoprostol\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"En cas d'échec du traitement utérotonique de première intention (perfusion et bolus IV d'ocytocine / Syntocinon® associés au massage utérin continu), les protocoles SONU recommandent en deuxième intention l'administration de prostaglandines, notamment 800 à 1 000 µg (4 à 5 comprimés de 200 µg) de misoprostol (Cytotec®) par voie intra-rectale, avant le tamponnement intra-utérin par ballonnet.\\n\\nSource : Cours de Gynéco-Obstétrique L3 / SONU — Conduite à tenir devant une hémorragie du post-partum par atonie utérine.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__7\",\n       \"num\": \"8\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les signes suivants permettent d'évoquer le diagnostic de môle hydatiforme :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une évolution inévitable vers un avortement complet\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Des métrorragies faites de sang rouge\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un taux très élevé de béta-hCG\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Des vomissements plus importants\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Une taille utérine en rapport avec l'âge de la grossesse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Des métrorragies faites de sang rouge ; C. Un taux très élevé de béta-hCG ; D. Des vomissements plus importants\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"La grossesse môlaire (môle hydatiforme) se manifeste au 1er trimestre par des métrorragies récidivantes d'abondance variable (sang rouge ou noirâtre), une exacerbation des signes sympathiques de grossesse (vomissements incoercibles, sialorrhée), un utérus anormalement volumineux (« en accordéon », plus gros que l'âge gestationnel) et une élévation massive des β-hCG plasmatiques.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Maladies trophoblastiques gestationnelles (môle hydatiforme).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__8\",\n       \"num\": \"9\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lesquel(s) de ces facteurs constitue(nt)-il(s) un (des) risque(s) pour le cancer du sein ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les anomalies du cycle menstruel\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La multiparité\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La ménopause tardive\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une première grossesse avant l'âge de 21 ans\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'obésité\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. La ménopause tardive ; E. L'obésité\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Les facteurs de risque du cancer du sein liés à une hyperœstrogénie prolongée comprennent la puberté précoce, la ménopause tardive (après 55 ans), la nulliparité ou une première grossesse tardive (après 30-35 ans) et l'obésité (production périphérique d'œstrogènes dans le tissu adipeux après la ménopause) ; la multiparité précoce est au contraire protectrice.\\n\\nSource : Cours de Gynéco-Obstétrique — Facteurs de risque du cancer du sein.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__9\",\n       \"num\": \"10\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La complication la plus fréquente du fibrome utérin au cours de la grossesse est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La suppuration du fibrome utérin\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La nécrobiose aseptique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La nécrobiose septique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les méno-métrorragies\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. La nécrobiose aseptique\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Sous l'effet de l'imprégnation hormonale gravidique, le fibrome augmente rapidement de volume ; sa vascularisation devenant insuffisante par rapport à sa croissance, il subit une ischémie aiguë appelée nécrobiose aseptique (douleur pelvienne vive localisée, fièvre modérée à 38 °C, utérus douloureux à la palpation), qui constitue sa complication la plus fréquente pendant la grossesse.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Fibrome utérin et grossesse (chap. 10).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'anémie est définie au premier trimestre de la grossesse par un taux d'hémoglobine inférieur à 11 g/dl.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Selon les critères de l'OMS, l'anémie chez la femme enceinte est définie par un taux d'hémoglobine inférieur à 11 g/dl aux 1er et 3e trimestres (et inférieur à 10,5 g/dl au 2e trimestre en raison de l'hémodilution physiologique maximale).\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Anémie et grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hypertension artérielle est considérée comme sévère si la tension artérielle systolique est supérieure ou égale à 55 mmHg.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Au cours de la grossesse, l'hypertension artérielle est définie comme sévère lorsque la tension artérielle systolique (TAS) est supérieure ou égale à 160 mmHg (16 cmHg) et/ou la tension artérielle diastolique (TAD) supérieure ou égale à 110 mmHg (11 cmHg), et non 55 mmHg.\\n\\nSource : Cours de Gynéco-Obstétrique L3 / SONU — Syndromes vasculo-rénaux : critères de gravité de l'HTA.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La prévention de la pré-éclampsie se fait par la prescription de l'acide acétylsalicylique (Aspirine) à partir de la 6ème semaine d'aménorrhée.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Chez les patientes à haut risque (antécédent de pré-éclampsie sévère précoce), la prévention par l'aspirine à faible dose (75 à 100 mg/jour) est instaurée à la fin du 1er trimestre / début du 2e trimestre, classiquement entre la 12ème et la 16ème semaine d'aménorrhée (avant 20 SA, phase d'invasion trophoblastique), et non dès 6 SA.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Prévention de la pré-éclampsie.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En cas de pré-éclampsie sévère, le médicament recommandé pour la prévention de la crise d'éclampsie est le diazépam (Valium).\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le médicament de référence recommandé en première intention pour prévenir et traiter les crises d'éclampsie chez une patiente atteinte de pré-éclampsie sévère est le sulfate de magnésium (MgSO4), beaucoup plus efficace et moins dépresseur respiratoire pour la mère et le nouveau-né que le diazépam (Valium®).\\n\\nSource : Cours SONU L3 / Gynéco-Obstétrique — Prise en charge de la pré-éclampsie sévère.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le cancer du col de l'utérus est considéré comme une maladie sexuellement transmissible dont le principal germe en cause est l'herpès virus simplex.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le principal agent responsable du cancer du col de l'utérus (dans plus de 95 à 99 % des cas) est le papillomavirus humain (HPV) à haut risque oncogène (notamment HPV 16 et 18), et non le virus de l'herpès simplex (HSV).\\n\\nSource : Cours de Gynéco-Obstétrique — Étiologie du cancer du col de l'utérus.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Des métrorragies faites de sang noirâtre, accompagnées d'une contracture de l'utérus et une disparition des bruits du cœur fœtal sont des signes classiques de l'hématome rétro-placentaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La triade symptomatique classique de l'hématome rétro-placentaire (HRP / décollement prématuré d'un placenta normalement inséré) associe une douleur abdominale brutale « en coup de poignard » avec hypertonie/contracture utérine (« utérus de bois »), des métrorragies peu abondantes de sang noirâtre incoagulable et une souffrance fœtale aiguë évoluant rapidement vers la disparition des BDCF.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Hémorragies du 3e trimestre : l'hématome rétro-placentaire (HRP).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__16\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les ménorragies sont des règles excessives en abondance et en durée.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les ménorragies désignent des saignements menstruels survenant à intervalles réguliers (à la date prévue des règles) mais anormalement abondants (> 80 ml) et/ou prolongés (> 7 jours), contrairement aux métrorragies qui surviennent en dehors des règles.\\n\\nSource : Cours de Gynéco-Obstétrique — Sémiologie des troubles du cycle menstruel.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La principale cause des dysménorrhées secondaires est l'endométriose.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Alors que les dysménorrhées primaires de l'adolescente sont fonctionnelles (liées aux prostaglandines), les dysménorrhées secondaires apparaissant plus tardivement chez la femme adulte sont dues dans la majorité des cas à l'endométriose (ou à l'adénomyose).\\n\\nSource : Cours de Gynéco-Obstétrique — Les dysménorrhées : étiologies.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__18\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le cancer du sein est un cancer dépendant de la production de la progestérone.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cancer du sein est classiquement défini comme un cancer œstrogéno-dépendant (lié principalement à une hyperœstrogénie relative ou prolongée stimulant la prolifération mammaire), et non uniquement dépendant de la production de progestérone.\\n\\nSource : Cours de Gynéco-Obstétrique — Facteurs hormonaux du cancer du sein.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__19\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le principal facteur de risque de la grossesse extra-utérine est l'infection de la trompe utérine.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les infections génitales hautes (salpingites aiguës ou chroniques, notamment à Chlamydia trachomatis et gonocoque) entraînent des lésions de l'épithélium cilié et des sténoses tubaires qui constituent le premier facteur de risque d'implantation ectopique de l'œuf (GEU).\\n\\nSource : Cours de Gynéco-Obstétrique — Grossesse extra-utérine (GEU) et salpingites aiguës (chap. 44).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le fer ne doit pas être prescrit chez les gestantes qui ont une drépanocytose majeure.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Chez les femmes enceintes atteintes d'une drépanocytose majeure (SS, SC, Sβ-thalassémie), l'anémie est d'origine hémolytique chronique et non ferriprive ; la prescription systématique de fer est contreindiquée en raison du risque d'hémochromatose secondaire (surcharge en fer aggravée par les transfusions), seule la supplémentation en acide folique étant recommandée.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Les hémoglobinopathies et grossesse (chap. 3).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de la grossesse, le dépistage de l'allo-immunisation rhésus se fait par le test de Coombs direct.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Chez la femme enceinte Rhésus négatif, le dépistage et la surveillance des agglutinines irrégulières anti-D dans le sérum maternel s'effectuent par le test de Coombs indirect (RAI : recherche d'agglutinines irrégulières) ; le test de Coombs direct se pratique chez le nouveau-né à la naissance sur le sang du cordon.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Allo-immunisation dans le système Rhésus au cours de la grossesse (chap. 4).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de l'accouchement de siège, il ne faut pas toucher au fœtus tant que les pointes des omoplates ne sont pas apparues.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Lors de l'expulsion en présentation du siège, l'abstention de toute traction intempestive (respect de l'expulsion spontanée jusqu'à l'apparition des pointes des omoplates à la vulve) est une règle d'or afin d'éviter le relèvement des bras et la déflexion de la tête dernière dans le détroit supérieur.\\n\\nSource : Cours de Gynéco-Obstétrique L3 / SONU — Conduite de l'accouchement du siège.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__23\",\n       \"num\": \"24\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'excès de toilette intime est un facteur favorisant des leucorrhées pathologiques.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les douches vaginales et l'hygiène intime excessive ou agressive détruisent la flore vaginale protectrice (bacilles de Döderlein / lactobacilles) et modifient le pH vaginal, favorisant la prolifération de germes pathogènes (Candida albicans, Gardnerella vaginalis) responsables de leucorrhées pathologiques.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Les infections génitales basses (chap. 43).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__24\",\n       \"num\": \"25\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lors de l'administration de la Sulfadoxine-Pyriméthamine chez la femme enceinte sous prophylaxie anti-anémique avec l'acide folique, il est recommandé dès la prise de la SulfadoxinePyriméthamine de suspendre durant 14 jours le traitement anti-anémique par l'acide folique si la dose de l'acide folique atteint ou dépasse 5 mg/jour et le reprendre au 15ème jour.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Des doses élevées d'acide folique (≥ 5 mg/jour) interfèrent par antagonisme métabolique avec l'action antifolique de la pyriméthamine contenue dans la SP, réduisant son efficacité antipaludique ; il convient donc de suspendre l'acide folique à forte dose pendant 14 jours après la prise de SP et de le reprendre au 15e jour (les doses faibles de 0,4 mg n'imposent pas d'arrêt).\\n\\nSource : Cours de Gynéco-Obstétrique — Chimioprophylaxie antipaludique (TPI-SP) et supplémentation martiale.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__25\",\n       \"num\": \"26\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Il existe une forme hémorragique de l'endométrite.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans les suites de couches, à côté de la forme classique suppurée (fièvre, lochies fétides purulentes, utérus gros et mou douloureux), il existe une forme clinique dite hémorragique de l'endométrite du post-partum responsable de métrorragies persistantes (hémorragie du post-partum tardif).\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Cat de la sage-femme en cas d'endométrite (suites de couches pathologiques).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__26\",\n       \"num\": \"27\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la lymphangite du sein, l'allaitement doit être interrompu.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La lymphangite aiguë du sein (placard inflammatoire rouge, chaud et douloureux du sein avec fièvre élevée mais sans pus dans le lait) est une inflammation superficielle des vaisseaux lymphatiques qui n'infecte pas le lait ; l'allaitement maternel doit être poursuivi (et intensifié pour bien drainer le sein) afin d'éviter l'évolution vers l'abcès du sein.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Affections mammaires des suites de couches.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__27\",\n       \"num\": \"28\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Il est interdit au cours de la grossesse d'injecter de l'ocytocine en intraveineuse directe.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Tant que le fœtus est in utero (pendant la grossesse et le travail avant l'expulsion), l'injection d'ocytocine en bolus intraveineux direct est formellement proscrite car elle déclenche une hypertonie utérine brutale entraînant une souffrance fœtale aiguë et un risque majeur de rupture utérine ; elle s'administre exclusivement en perfusion diluée à débit contrôlé.\\n\\nSource : Cours de Gynéco-Obstétrique L3 / SONU — Surveillance d'une perfusion d'ocytocine.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__28\",\n       \"num\": \"29\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le traitement de l'anémie ferriprive si le taux d'hémoglobine est supérieur ou égal à 8 g/dl repose sur l'administration de fer sous forme ferreuse à raison de 100 mg de fer élément / jour en 2 ou 3 prises.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans le traitement curatif d'une anémie ferriprive modérée pendant la grossesse (taux d'hémoglobine compris entre 8 et 11 g/dl, bien tolérée), la posologie recommandée est de 100 à 120 mg de fer élément par jour par voie orale (sels ferreux) répartis en 2 ou 3 prises pendant au moins 3 mois.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Traitement de l'anémie ferriprive au cours de la grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__29\",\n       \"num\": \"30\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les cas de paludisme grave doivent être pris en charge au sein d'une formation sanitaire SONU-B.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les structures SONU-B (Soins Obstétricaux et Néonataux d'Urgence de Base, centres de santé périphériques) ne disposent ni de plateau technique complet ni de capacité de transfusion sanguine ou de réanimation lourde ; les cas de paludisme grave chez la femme enceinte doivent être référés vers un hôpital de référence offrant des soins complets (SONU-C).\\n\\nSource : Cours SONU L3 / Paludisme et grossesse — Niveaux de prise en charge SONU-B et SONU-C.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ou les complications obstétricales de la COVID-19 est ou sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"malformation fœtale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"hydramnios\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"souffrance fœtale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"pré-éclampsie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"accouchement prématuré\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. souffrance fœtale ; D. pré-éclampsie ; E. accouchement prématuré\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"L'infection au SARS-CoV-2 (COVID-19) chez la femme enceinte augmente significativement le risque de complications obstétricales et périnatales, notamment l'accouchement prématuré (spontané ou induit), les syndromes hypertensifs à type de pré-éclampsie et la souffrance fœtale (par hypoxie maternelle et atteinte vasculaire placentaire), sans effet tératogène démontré.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Infection au COVID-19 et grossesse (chap. 6).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ou les conditions de réalisation de l'épreuve du travail est ou sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Bassin maternel rétréci\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Présentation céphalique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Milieu obstétrico-chirurgical comprenant un bloc opératoire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Fœtus à terme de poids normal\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Absence de souffrance fœtale chronique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Bassin maternel rétréci ; B. Présentation céphalique ; C. Milieu obstétrico-chirurgical comprenant un bloc opératoire ; D. Fœtus à terme de poids normal ; E. Absence de souffrance fœtale chronique\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"L'épreuve du travail requiert la réunion stricte de toutes ces conditions : un bassin rétréci limite (chirurgicalement franchissable), une présentation céphalique bien fléchie (sommet), un fœtus unique eutrophique sans macrosomie, l'absence de souffrance fœtale préalable (et d'utérus cicatriciel) et la réalisation impérative en milieu obstétrico-chirurgical disposant d'un bloc opératoire fonctionnel.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — L'épreuve du travail : conditions de réalisation.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ou les complications de l'anémie ferriprive sur l'évolution de la grossesse est ou sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"infection urinaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"retard de croissance intra-utérin\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"endométrite\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"accouchement prématuré\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"hydramnios\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. infection urinaire ; B. retard de croissance intra-utérin ; C. endométrite ; D. accouchement prématuré\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"L'anémie ferriprive maternelle diminue les défenses immunitaires (favorisant les infections urinaires gravidiques et l'endométrite du post-partum) et altère l'oxygénation fœto-placentaire, exposant au retard de croissance intra-utérin (RCIU / hypotrophie) et à l'accouchement prématuré. Elle n'entraîne pas d'hydramnios.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Retentissement et complications de l'anémie au cours de la grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les drépanocytoses majeures sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"AC\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"SAFA2\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"AS\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"SC\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"SFA2\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. SC ; E. SFA2\",\n       \"answerLetters\": [\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Les syndromes drépanocytaires majeurs regroupent l'homozygotie SS, l'hétérozygotie composite SC et les Sβ-thalassémies (notées SFA2 à l'électrophorèse de l'hémoglobine en cas de Sβ+-thalassémie, ou SF en cas de Sβ0-thalassémie). Les formes AS et AC sont des traits hétérozygotes mineurs asymptomatiques.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Classification des hémoglobinopathies et drépanocytoses majeures (chap. 3).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le ou les facteur(s) favorisant l'endométrite est ou sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La Rupture Prématurée des Membranes supérieure à 12 heures\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'hémorragie de la délivrance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le transfert précoce des parturientes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les touchers vaginaux aseptiques\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le travail d'accouchement prolongé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. La Rupture Prématurée des Membranes supérieure à 12 heures ; B. L'hémorragie de la délivrance ; E. Le travail d'accouchement prolongé\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"L'endométrite du post-partum est une infection ascendante de l'endomètre favorisée par l'ouverture prolongée de l'œuf (rupture prématurée ou précoce des membranes > 12 heures), le travail prolongé, les manœuvres endo-utérines et l'hémorragie de la délivrance (qui diminue les défenses locales et nécessite souvent une révision utérine).\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Facteurs favorisants de l'endométrite du post-partum.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La cystite aiguë se manifeste par les signes suivants :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les mictions impérieuses\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La brûlure urétrale basse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La pollakiurie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La douleur lombaire\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La fièvre\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Les mictions impérieuses ; B. La brûlure urétrale basse ; C. La pollakiurie\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"La cystite aiguë est une infection urinaire basse caractérisée par la triade fonctionnelle urinaire apyrétique : pollakiurie, brûlures mictionnelles (urétrales basses) et impériosités mictionnelles (mictions impérieuses), sans fièvre ni douleur lombaire (qui signent au contraire une pyélonéphrite aiguë).\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Les infections urinaires et grossesse (p. 113).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle ou lesquelles des assertions concernant la rubéole au cours de la grossesse est ou sont juste(s) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Il faut nécessairement réaliser la sérologie au cours du 1er trimestre de grossesse.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Elle peut se compliquer d'avortements spontanés\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'une de ses mesures prophylactiques est la vaccination des fillettes en âge scolaire immunisées.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les anticorps M apparaissent en cas de réinfection.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Les risques surviennent uniquement en cas de primo-infection de la rubéole au cours de la grossesse.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Il faut nécessairement réaliser la sérologie au cours du 1er trimestre de grossesse. ; B. Elle peut se compliquer d'avortements spontanés\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"La sérologie de la rubéole est un examen obligatoire du 1er trimestre de grossesse (Priorité 6 du bilan prénatal) ; la rubéole gravidique peut entraîner des avortements spontanés, une mort fœtale ou des malformations congénitales (syndrome de Gregg). La vaccination cible les fillettes non immunisées, les IgM signent une primo-infection (absentes lors d'une réinfection), et un faible risque existe exceptionnellement lors d'une réinfection précoce.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Sérologies et grossesse : la rubéole (chap. 5).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au troisième trimestre de grossesse, l'échographie :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"permet d'apprécier le comportement fœtal\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"permet de préciser la présentation fœtale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"se réalise idéalement entre 32 et 34 semaines d'aménorrhées\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"permet l'étude de la qualité de l'œuf\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"permet d'apprécier l'état des annexes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. permet d'apprécier le comportement fœtal ; B. permet de préciser la présentation fœtale ; C. se réalise idéalement entre 32 et 34 semaines d'aménorrhées ; E. permet d'apprécier l'état des annexes\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"L'échographie du 3e trimestre (réalisée entre 30 et 34 SA, classiquement 32-34 SA) apprécie la croissance/biométrie fœtale, la vitalité et le comportement fœtal (mouvements actifs, mouvements respiratoires, score de Manning), la présentation fœtale et les annexes (localisation définitive du placenta et quantité de liquide amniotique). L'étude de la qualité de l'œuf relève du 1er trimestre.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Explorations en obstétrique : l'échographie obstétricale (p. 192).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle ou lesquelles des assertions concernant la présentation de siège est ou sont juste(s) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le repère de la présentation du siège est le coccyx du fœtus.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La prématurité est une étiologie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"En cas de siège complet le segment inférieur est bien formé et épais.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"À dilatation complète du col mettre en place une perfusion de syntocinon* 5 UI dans 500 ml de sérum glucosé isotonique\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le foyer maximal des bruits du cœur fœtal est entendu au-dessous et en dehors de l'ombilic\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Le repère de la présentation du siège est le coccyx du fœtus. ; B. La prématurité est une étiologie ; D. À dilatation complète du col mettre en place une perfusion de syntocinon* 5 UI dans 500 ml de sérum glucosé isotonique\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Dans la présentation du siège, le repère fœtal est le sacrum/coccyx, la prématurité est une étiologie fréquente (culbute physiologique non achevée), et à dilatation complète une perfusion d'ocytocine (5 UI dans 500 ml de SGI) est installée pour renforcer les contractions lors de l'expulsion. Le foyer des BDCF s'entend au-dessus de l'ombilic, et le segment inférieur est mal amplié dans le siège complet.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — La présentation du siège.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j9-sf3__39\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les indications de l'hystérosalpingographie sont : (3 RÉPONSES JUSTES)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"bilan d'infertilité\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"recherche de malformations utérines\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"bilan de ménométrorragies\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"recherche d'anomalies de l'ovaire\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"recherche d'étiologies de douleurs pelviennes chroniques\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. bilan d'infertilité ; B. recherche de malformations utérines ; C. bilan de ménométrorragies\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Selon le cours sur les explorations fonctionnelles en gynécologie (p. 190), l'hystérosalpingographie (HSG) explore la cavité utérine et la perméabilité tubaire et a pour principales indications : l'étude de la perméabilité des trompes dans le bilan d'infertilité, la recherche de malformations utérines (après avortements à répétition) et la recherche de la cause d'un saignement d'origine utérine (bilan de ménométrorragies). Elle ne permet pas d'explorer les ovaires.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Les explorations fonctionnelles en gynécologie : l'hystérosalpingographie (p. 190). CORRIGÉ EXPLIQUÉ — PRÉPA DE INFAS\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J9 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
